//! Synthetic fixtures shared by the `text_*` tests: the four-glyph font of `fonts.md` §13.1
//! and helpers to build faces, character lists and canvases. Everything here is generated by
//! our own code; no game data.

#![allow(dead_code)]

use std::sync::Arc;

use tessera_formats::font::{Font, Glyph};
use tessera_formats::{Did, Record};
use tessera_ui::paint::CoverageMap;
use tessera_ui::text::{CharListBuilder, FontFace, FontId, TextChar};

/// DID of the §13.1 font.
pub const FONT_DID: u32 = 0x42AB_0001;
/// Its foreground atlas.
pub const FG_DID: u32 = 0x41AB_0010;
/// Its background atlas.
pub const BG_DID: u32 = 0x41AB_0011;
/// Coverage written into every foreground glyph box with ink.
pub const FG_INK: u8 = 200;
/// Coverage written into every background bordered box with ink.
pub const BG_INK: u8 = 90;

/// The 80 bytes of `fonts.md` §13.1.
pub const RECORD_13_1: &str = "
01 00 ab 42 0a 00 00 00 06 00 00 00 04 00 00 00
03 0a 00 01 00 20 00 01 00 01 00 04 07 00 01 01
3f 00 06 00 01 00 06 07 00 01 01 41 00 0c 00 01
00 03 08 fe 01 02 6a 00 14 00 01 00 01 00 00 00
01 00 00 00 08 00 00 00 10 00 ab 41 11 00 ab 41";

/// Hex text → bytes.
pub fn hex(s: &str) -> Vec<u8> {
    s.split_whitespace()
        .map(|b| u8::from_str_radix(b, 16).expect("hex byte"))
        .collect()
}

/// A glyph entry.
#[allow(clippy::too_many_arguments)]
pub const fn g(w: u8, h: u8, a: i8, b: i8, t: i8, code: u16, x: u16, y: u16) -> Glyph {
    Glyph {
        width: w,
        height: h,
        left_bearing: a,
        right_bearing: b,
        top: t,
        code,
        x,
        y,
    }
}

/// The glyphs of §13.1.
pub fn glyphs_13_1() -> Vec<Glyph> {
    vec![
        g(3, 10, 0, 1, 0, 0x20, 1, 1),
        g(4, 7, 0, 1, 1, 0x3F, 6, 1),
        g(6, 7, 0, 1, 1, 0x41, 12, 1),
        g(3, 8, -2, 1, 2, 0x6A, 20, 1),
    ]
}

/// A render-surface payload (`records.md` §5): DID, category, width, height, format code
/// 28 (A8), data length, data.
pub fn surface_payload(did: u32, category: u32, w: u32, h: u32, data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    for v in [did, category, w, h, 28, data.len() as u32] {
        out.extend_from_slice(&v.to_le_bytes());
    }
    out.extend_from_slice(data);
    out
}

/// Atlases for `glyphs`: the foreground has [`FG_INK`] in every box of a glyph with ink
/// (everything but the space), the background [`BG_INK`] in every bordered box.
pub fn atlases(glyphs: &[Glyph], border: u32, w: u32, h: u32) -> (Vec<u8>, Vec<u8>) {
    let mut fg = vec![0u8; (w * h) as usize];
    let mut bg = vec![0u8; (w * h) as usize];
    for gl in glyphs {
        if gl.code == 0x20 {
            continue;
        }
        let (x0, y0) = (u32::from(gl.x), u32::from(gl.y));
        for y in y0..y0 + u32::from(gl.height) {
            for x in x0..x0 + u32::from(gl.width) {
                fg[(y * w + x) as usize] = FG_INK;
            }
        }
        for y in y0 - border..y0 + u32::from(gl.height) + border {
            for x in x0 - border..x0 + u32::from(gl.width) + border {
                bg[(y * w + x) as usize] = BG_INK;
            }
        }
    }
    (fg, bg)
}

/// The §13.1 font built from its bytes and synthetic atlases through
/// [`FontFace::from_payloads`]; `with_background` false gives the same font with background
/// DID 0 and borders 0 (the stamped outline of §8.3).
pub fn face_13_1(with_background: bool) -> Arc<FontFace> {
    let (fg, bg) = atlases(&glyphs_13_1(), 1, 32, 12);
    let fgp = surface_payload(FG_DID, 13, 32, 12, &fg);
    if with_background {
        let bgp = surface_payload(BG_DID, 13, 32, 12, &bg);
        Arc::new(FontFace::from_payloads(&hex(RECORD_13_1), &fgp, Some(&bgp)).expect("face"))
    } else {
        let font = Font::new(
            Did(FONT_DID),
            10,
            6,
            glyphs_13_1(),
            0,
            0,
            8,
            Did(FG_DID),
            Did(0),
        );
        let bytes = tessera_formats::font::encode_font(&font);
        assert!(Font::parse(&bytes).is_ok());
        Arc::new(FontFace::from_payloads(&bytes, &fgp, None).expect("face"))
    }
}

/// A face from parts with a blank `w × h` atlas.
pub fn face(line_height: u32, baseline: u32, glyphs: Vec<Glyph>, w: u32, h: u32) -> Arc<FontFace> {
    let map = Arc::new(CoverageMap::new(w, h, vec![0; (w * h) as usize]).expect("map"));
    Arc::new(
        FontFace::from_parts(
            FontId::Data(0x4200_0000),
            line_height,
            baseline,
            [0, 0],
            glyphs,
            map,
            None,
        )
        .expect("face"),
    )
}

/// `text` as plain characters in the normal slot, opaque white.
pub fn chars(text: &str) -> Vec<TextChar> {
    let mut b = CharListBuilder::new();
    b.push_str(text);
    b.finish()
}

/// Line texts of a layout (characters `start..end`), as strings.
pub fn line_texts(l: &tessera_ui::text::TextLayout, cs: &[TextChar]) -> Vec<String> {
    l.lines
        .iter()
        .map(|ln| {
            String::from_utf16_lossy(
                &cs[ln.start..ln.end]
                    .iter()
                    .map(|c| c.unit)
                    .collect::<Vec<_>>(),
            )
        })
        .collect()
}
